package chamele0nx

import (
	"crypto/rand"
	"encoding/binary"
	"encoding/json"
	"fmt"
	"math"
	"os"
	"strings"
	"time"
)

// SiteProfile describes the TLS-level traffic fingerprint of a real website.
// Chamele0nX shapes VPN traffic to match this profile so DPI cannot distinguish
// it from real browsing. Generated by chamele0nx-profiler, loaded at runtime.
//
// All fields describe what DPI sees at the TLS record layer — NOT HTTP/2 content.
type SiteProfile struct {
	// Name is a human-readable identifier (e.g., "saas-dashboard-v1").
	Name string `json:"name"`

	// Version for profile format compatibility.
	Version int `json:"version"`

	// RecordSizeDistribution describes the distribution of TLS record payload
	// sizes. Each bucket has a min/max size range and a weight (probability).
	// The shaper picks sizes from this distribution to construct bursts.
	RecordSizeDistribution []SizeBucket `json:"record_size_distribution"`

	// BurstPattern describes page-load-like bursts.
	BurstPattern BurstPattern `json:"burst_pattern"`

	// SessionProfile describes session-level characteristics.
	SessionProfile SessionProfile `json:"session_profile"`

	// UploadDownloadRatio is the ratio of bytes uploaded to downloaded.
	// Real browsing is typically 1:10 to 1:50 (mostly downloading).
	UploadDownloadRatio float64 `json:"upload_download_ratio"`

	// ConcurrentStreams is the typical number of HTTP/2 streams open.
	ConcurrentStreams Range `json:"concurrent_streams"`

	// BypassPauseCap opts this profile out of the ShapedConn inline
	// burst-pause cap (maxBurstPauseInWrite = 250ms). Set true only for
	// profiles where long pauses are the feature (e.g. Stealth mode
	// trades throughput for timing disguise). Default false — practical
	// profiles stay under the cap to avoid stalling interactive streams.
	BypassPauseCap bool `json:"bypass_pause_cap,omitempty"`
}

// SizeBucket represents a bin in the record size distribution histogram.
type SizeBucket struct {
	MinSize int     `json:"min_size"` // minimum payload size (bytes)
	MaxSize int     `json:"max_size"` // maximum payload size (bytes)
	Weight  float64 `json:"weight"`   // relative probability (0-1, sum to 1)
}

// BurstPattern describes the timing pattern of TLS record bursts.
type BurstPattern struct {
	// RecordsPerBurst is the number of TLS records in a single burst (page load).
	RecordsPerBurst Range `json:"records_per_burst"`

	// BurstDuration is how long a burst takes (all records sent within this window).
	BurstDuration DurationRange `json:"burst_duration"`

	// InterBurstPause is the pause between bursts (simulates reading time).
	InterBurstPause DurationRange `json:"inter_burst_pause"`

	// InterRecordDelay is the delay between consecutive records within a burst.
	InterRecordDelay DurationRange `json:"inter_record_delay"`
}

// SessionProfile describes session-level characteristics visible to DPI.
type SessionProfile struct {
	// Duration is the total session length before disconnect/reconnect.
	Duration DurationRange `json:"duration"`

	// BurstsPerSession is the typical number of bursts per session.
	BurstsPerSession Range `json:"bursts_per_session"`

	// TotalBytesPerSession is the expected volume per session.
	TotalBytesPerSession Range `json:"total_bytes_per_session"`
}

// Range represents a min/max integer range.
type Range struct {
	Min int `json:"min"`
	Max int `json:"max"`
}

// DurationRange represents a min/max duration range.
type DurationRange struct {
	Min time.Duration `json:"min"`
	Max time.Duration `json:"max"`
}

// MarshalJSON implements custom JSON marshaling for DurationRange (as ms).
func (d DurationRange) MarshalJSON() ([]byte, error) {
	return json.Marshal(struct {
		MinMs int64 `json:"min_ms"`
		MaxMs int64 `json:"max_ms"`
	}{
		MinMs: d.Min.Milliseconds(),
		MaxMs: d.Max.Milliseconds(),
	})
}

// UnmarshalJSON implements custom JSON unmarshaling for DurationRange (from ms).
func (d *DurationRange) UnmarshalJSON(data []byte) error {
	var v struct {
		MinMs int64 `json:"min_ms"`
		MaxMs int64 `json:"max_ms"`
	}
	if err := json.Unmarshal(data, &v); err != nil {
		return err
	}
	d.Min = time.Duration(v.MinMs) * time.Millisecond
	d.Max = time.Duration(v.MaxMs) * time.Millisecond
	return nil
}

// LoadProfile reads a SiteProfile from a JSON file.
func LoadProfile(path string) (*SiteProfile, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read profile: %w", err)
	}
	var p SiteProfile
	if err := json.Unmarshal(data, &p); err != nil {
		return nil, fmt.Errorf("parse profile: %w", err)
	}
	if err := p.Validate(); err != nil {
		return nil, fmt.Errorf("invalid profile: %w", err)
	}
	return &p, nil
}

// Validate checks that the profile has sane values.
func (p *SiteProfile) Validate() error {
	if p.Version != 1 {
		return fmt.Errorf("unsupported version %d", p.Version)
	}
	if len(p.RecordSizeDistribution) == 0 {
		return fmt.Errorf("empty record size distribution")
	}
	totalWeight := 0.0
	for _, b := range p.RecordSizeDistribution {
		if b.MinSize < minTLSRecord || b.MaxSize > maxTLSRecord {
			return fmt.Errorf("bucket [%d, %d] outside TLS record bounds [%d, %d]",
				b.MinSize, b.MaxSize, minTLSRecord, maxTLSRecord)
		}
		if b.MinSize > b.MaxSize {
			return fmt.Errorf("bucket min %d > max %d", b.MinSize, b.MaxSize)
		}
		if b.Weight < 0 {
			return fmt.Errorf("negative weight %f", b.Weight)
		}
		totalWeight += b.Weight
	}
	if math.Abs(totalWeight-1.0) > 0.01 {
		return fmt.Errorf("weights sum to %f, expected ~1.0", totalWeight)
	}
	if p.BurstPattern.RecordsPerBurst.Min <= 0 {
		return fmt.Errorf("records per burst min must be > 0")
	}
	if p.UploadDownloadRatio <= 0 || p.UploadDownloadRatio > 1 {
		return fmt.Errorf("upload/download ratio must be in (0, 1], got %f", p.UploadDownloadRatio)
	}
	return nil
}

// DefaultSaaSProfile returns a built-in profile mimicking a typical SaaS
// dashboard (e.g., analytics app, project management tool).
// This is used as a fallback if no custom profile is loaded.
//
// Alias: DefaultBalancedProfile (same shape, different name for the
// public preset switch in [BuiltInProfileByName]).
//
// v2: InterBurstPause was tightened from 2–30s to 50–250ms. The original
// range reflected what a real human-driven dashboard session looks like,
// but ShapedConn injects pauses inline under writeMu which blocks every
// HTTP/2 stream on the connection. 2–30s would stall interactive traffic
// for seconds at a time. 50–250ms gives ML-DPI timing entropy without
// user-visible latency spikes on chat / tab-switching traffic.
func DefaultSaaSProfile() *SiteProfile {
	return &SiteProfile{
		Name:    "saas-dashboard-default",
		Version: 1,
		RecordSizeDistribution: []SizeBucket{
			{MinSize: 64, MaxSize: 200, Weight: 0.15},      // small API responses, headers
			{MinSize: 200, MaxSize: 800, Weight: 0.25},     // JSON API payloads
			{MinSize: 800, MaxSize: 2000, Weight: 0.25},    // medium responses
			{MinSize: 2000, MaxSize: 5000, Weight: 0.20},   // larger JSON/HTML chunks
			{MinSize: 5000, MaxSize: 10000, Weight: 0.10},  // JS/CSS chunks
			{MinSize: 10000, MaxSize: 16384, Weight: 0.05}, // large assets
		},
		BurstPattern: BurstPattern{
			RecordsPerBurst:  Range{Min: 5, Max: 15},
			BurstDuration:    DurationRange{Min: 500 * time.Millisecond, Max: 2 * time.Second},
			InterBurstPause:  DurationRange{Min: 50 * time.Millisecond, Max: 250 * time.Millisecond},
			InterRecordDelay: DurationRange{Min: 0, Max: 50 * time.Millisecond},
		},
		SessionProfile: SessionProfile{
			Duration:             DurationRange{Min: 3 * time.Minute, Max: 15 * time.Minute},
			BurstsPerSession:     Range{Min: 5, Max: 30},
			TotalBytesPerSession: Range{Min: 500_000, Max: 10_000_000},
		},
		UploadDownloadRatio: 0.1, // 1:10 upload:download
		ConcurrentStreams:   Range{Min: 1, Max: 6},
	}
}

// DefaultBalancedProfile is the explicit alias for [DefaultSaaSProfile].
// Identical shape — exists so the public preset name "balanced" maps to a
// real function rather than going through a string-named alias.
func DefaultBalancedProfile() *SiteProfile { return DefaultSaaSProfile() }

// DefaultStealthProfile returns a built-in profile optimized for **maximum
// DPI evasion at the cost of throughput**. The defining characteristics:
//
//   - Heavy bias toward small (64–800 byte) records — looks like API
//     polling, NOT bulk transfer
//   - Long inter-burst pauses (10–120s) — simulates a user reading rather
//     than continuously downloading
//   - Small bursts (2–5 records) and slow burst durations (1–4s)
//   - Lower concurrent stream count (1–3)
//
// Use this when DPI is aggressively flagging high-volume sessions or when
// the cover site profile that survives passive DPI is a low-traffic admin
// console rather than a media-rich SaaS dashboard.
//
// Throughput cap: realistic ≤2-5 Mbps for sustained transfers.
// v2: Stealth keeps longer pauses (200–800ms) AND sets BypassPauseCap=true
// so the ShapedConn cap does not clamp it. This is the one profile where
// multi-hundred-ms stalls are the feature, not the bug — stealth trades
// throughput for pauses that look genuinely like a human idling on an
// admin console. User-visible latency spikes on interactive traffic are
// expected and accepted in this mode.
func DefaultStealthProfile() *SiteProfile {
	return &SiteProfile{
		Name:           "stealth-admin-console",
		Version:        1,
		BypassPauseCap: true,
		RecordSizeDistribution: []SizeBucket{
			{MinSize: 64, MaxSize: 200, Weight: 0.40},    // small headers / heartbeats
			{MinSize: 200, MaxSize: 800, Weight: 0.40},   // small JSON polls
			{MinSize: 800, MaxSize: 2000, Weight: 0.15},  // occasional medium response
			{MinSize: 2000, MaxSize: 5000, Weight: 0.05}, // rare larger chunk
		},
		BurstPattern: BurstPattern{
			RecordsPerBurst:  Range{Min: 2, Max: 5},
			BurstDuration:    DurationRange{Min: 1 * time.Second, Max: 4 * time.Second},
			InterBurstPause:  DurationRange{Min: 200 * time.Millisecond, Max: 800 * time.Millisecond},
			InterRecordDelay: DurationRange{Min: 5 * time.Millisecond, Max: 200 * time.Millisecond},
		},
		SessionProfile: SessionProfile{
			Duration:             DurationRange{Min: 5 * time.Minute, Max: 30 * time.Minute},
			BurstsPerSession:     Range{Min: 3, Max: 15},
			TotalBytesPerSession: Range{Min: 50_000, Max: 1_500_000},
		},
		UploadDownloadRatio: 0.2, // closer 1:5, like an admin form-submit pattern
		ConcurrentStreams:   Range{Min: 1, Max: 3},
	}
}

// DefaultAggressiveProfile returns a built-in profile **biased for
// throughput, not concealment**. Large records, short pauses, many
// concurrent streams. Use this on networks where DPI is permissive (or
// not deployed) and the operator just wants the tunnel to feel fast.
//
// **Warning** — this profile is the easiest one for ML-based DPI to flag,
// because the burst-pause distribution drifts away from the "human reading"
// pattern. This is NOT a general "performance mode" — it is a deliberate
// trade for situations where stealth is not the binding constraint.
//
// Throughput cap: realistic ≤25 Mbps depending on RTT.
// v2: Aggressive tightens InterBurstPause to 20–150ms for throughput.
// Values above the 250ms cap would be clamped anyway, and this profile's
// entire point is "stealth-off, throughput-on" — shorter pauses match the
// bulk-transfer goal better than the cap-clamped old range.
func DefaultAggressiveProfile() *SiteProfile {
	return &SiteProfile{
		Name:    "aggressive-bulk-transfer",
		Version: 1,
		RecordSizeDistribution: []SizeBucket{
			{MinSize: 200, MaxSize: 2000, Weight: 0.10},    // headers
			{MinSize: 2000, MaxSize: 5000, Weight: 0.15},   // small chunks
			{MinSize: 5000, MaxSize: 10000, Weight: 0.25},  // medium
			{MinSize: 10000, MaxSize: 16384, Weight: 0.50}, // large — bulk
		},
		BurstPattern: BurstPattern{
			RecordsPerBurst:  Range{Min: 15, Max: 40},
			BurstDuration:    DurationRange{Min: 200 * time.Millisecond, Max: 1 * time.Second},
			InterBurstPause:  DurationRange{Min: 20 * time.Millisecond, Max: 150 * time.Millisecond},
			InterRecordDelay: DurationRange{Min: 0, Max: 5 * time.Millisecond},
		},
		SessionProfile: SessionProfile{
			Duration:             DurationRange{Min: 1 * time.Minute, Max: 10 * time.Minute},
			BurstsPerSession:     Range{Min: 30, Max: 200},
			TotalBytesPerSession: Range{Min: 5_000_000, Max: 100_000_000},
		},
		UploadDownloadRatio: 0.05, // 1:20, very download-heavy (streaming-like)
		ConcurrentStreams:   Range{Min: 4, Max: 16},
	}
}

// DefaultSaaSStealthProfile returns the built-in twin of the shipped
// deployment profile in deploy/profiles/saas-stealth.example.json.
//
// Why this exists: the server side of a deployment is configured with a
// named profile ("saas-stealth"), and a share link minted from that
// server carries the same name to the client. Before this constructor
// existed the client had no built-in by that name, so the resolver fell
// through to the filesystem-path branch and tried to open a file called
// "saas-stealth" that does not exist on the client — every connection
// died with "load profile: open saas-stealth: no such file or directory".
// Resolving the name to a struct instead keeps such a link working.
//
// Honest caveat carried over from the JSON _comment: this shape was
// authored for this repository as an illustration. It was not captured
// from any site and not measured from real traffic. An operator running
// it unmodified is running the same fingerprint as every other reader of
// this repository — one classifier fits them all. Capture your own with
// chamele0nx-profiler and keep it private rather than lean on this.
//
// It is a distinct shape from DefaultStealthProfile (the "stealth"
// preset): larger record buckets, bigger bursts, and shorter pauses.
// Like the stealth admin-console preset it sets BypassPauseCap=true —
// the JSON sets bypass_pause_cap, so the 140–1050ms inter-burst pauses
// are the intended feature and must not be clamped by the ShapedConn cap.
func DefaultSaaSStealthProfile() *SiteProfile {
	return &SiteProfile{
		Name:           "saas-stealth",
		Version:        1,
		BypassPauseCap: true,
		RecordSizeDistribution: []SizeBucket{
			{MinSize: 96, MaxSize: 512, Weight: 0.34},
			{MinSize: 512, MaxSize: 1800, Weight: 0.31},
			{MinSize: 1800, MaxSize: 5200, Weight: 0.24},
			{MinSize: 5200, MaxSize: 11000, Weight: 0.11},
		},
		BurstPattern: BurstPattern{
			RecordsPerBurst:  Range{Min: 5, Max: 19},
			BurstDuration:    DurationRange{Min: 180 * time.Millisecond, Max: 1400 * time.Millisecond},
			InterBurstPause:  DurationRange{Min: 140 * time.Millisecond, Max: 1050 * time.Millisecond},
			InterRecordDelay: DurationRange{Min: 2 * time.Millisecond, Max: 17 * time.Millisecond},
		},
		SessionProfile: SessionProfile{
			Duration:             DurationRange{Min: 240000 * time.Millisecond, Max: 2100000 * time.Millisecond},
			BurstsPerSession:     Range{Min: 35, Max: 260},
			TotalBytesPerSession: Range{Min: 4_000_000, Max: 72_000_000},
		},
		UploadDownloadRatio: 0.09,
		ConcurrentStreams:   Range{Min: 1, Max: 5},
	}
}

// DefaultSaaSFastProfile returns the built-in twin of the shipped
// deployment profile in deploy/profiles/saas-fast.example.json.
//
// Why this exists: same reason as DefaultSaaSStealthProfile — a server
// configured with the "saas-fast" profile mints share links naming it,
// and without a built-in of that name the client would treat "saas-fast"
// as a filesystem path and fail to connect. Resolving the name here keeps
// those links working without shipping the JSON onto the device.
//
// Honest caveat carried over from the JSON _comment: this shape was
// authored for this repository as an illustration. It was not captured
// from any site and not measured from real traffic. An operator running
// it unmodified is running the same fingerprint as every other reader of
// this repository — one classifier fits them all. Capture your own with
// chamele0nx-profiler and keep it private rather than lean on this.
//
// This is deliberately NOT an alias for DefaultAggressiveProfile: the two
// differ materially. saas-fast fires 34–76 records per burst (aggressive:
// 15–40), pauses 4–22ms between bursts (aggressive: 20–150ms), and opens
// 2–7 concurrent streams (aggressive: 4–16). Aliasing them would silently
// substitute a different fingerprint than the server was configured for.
func DefaultSaaSFastProfile() *SiteProfile {
	return &SiteProfile{
		Name:    "saas-fast",
		Version: 1,
		RecordSizeDistribution: []SizeBucket{
			{MinSize: 128, MaxSize: 1100, Weight: 0.08},
			{MinSize: 1100, MaxSize: 3400, Weight: 0.14},
			{MinSize: 3400, MaxSize: 9200, Weight: 0.27},
			{MinSize: 9200, MaxSize: 15600, Weight: 0.51},
		},
		BurstPattern: BurstPattern{
			RecordsPerBurst:  Range{Min: 34, Max: 76},
			BurstDuration:    DurationRange{Min: 120 * time.Millisecond, Max: 900 * time.Millisecond},
			InterBurstPause:  DurationRange{Min: 4 * time.Millisecond, Max: 22 * time.Millisecond},
			InterRecordDelay: DurationRange{Min: 0, Max: 2 * time.Millisecond},
		},
		SessionProfile: SessionProfile{
			Duration:             DurationRange{Min: 210000 * time.Millisecond, Max: 1500000 * time.Millisecond},
			BurstsPerSession:     Range{Min: 90, Max: 460},
			TotalBytesPerSession: Range{Min: 80_000_000, Max: 420_000_000},
		},
		UploadDownloadRatio: 0.06,
		ConcurrentStreams:   Range{Min: 2, Max: 7},
	}
}

// DefaultSaaSMaxProfile returns the built-in twin of the shipped
// deployment profile in deploy/profiles/saas-max.example.json.
//
// Why this exists: same reason as the other two deployment twins — a
// server configured with the "saas-max" profile mints share links naming
// it, and without a built-in of that name the client treats "saas-max" as
// a filesystem path, cannot open it, and fails the connect outright.
// Resolving the name here keeps such a link working with no JSON on disk.
//
// Honest caveat carried over from the JSON _comment: this shape was
// authored for this repository as an illustration. It was not captured
// from any site and not measured from real traffic. An operator running
// it unmodified is running the same fingerprint as every other reader of
// this repository — one classifier fits them all. Capture your own with
// chamele0nx-profiler and keep it private rather than lean on this.
//
// This is the throughput end of the shipped range and the weakest
// disguise of the three: nothing under 2600 bytes, two thirds of the
// weight in the top bucket, 75–210 records per burst and 2–9ms between
// bursts. That is close to continuous large-record output, which is
// close to what an unshaped tunnel looks like. Prefer saas-fast unless
// throughput is genuinely the binding constraint, and do not treat this
// as a general "performance mode".
//
// It is distinct from both DefaultAggressiveProfile and
// DefaultSaaSFastProfile — bigger bursts, shorter pauses, a floor of 2600
// bytes instead of 128 — so it must not be aliased to either.
func DefaultSaaSMaxProfile() *SiteProfile {
	return &SiteProfile{
		Name:    "saas-max",
		Version: 1,
		RecordSizeDistribution: []SizeBucket{
			{MinSize: 2600, MaxSize: 7400, Weight: 0.12},
			{MinSize: 7400, MaxSize: 11200, Weight: 0.22},
			{MinSize: 11200, MaxSize: 15800, Weight: 0.66},
		},
		BurstPattern: BurstPattern{
			RecordsPerBurst:  Range{Min: 75, Max: 210},
			BurstDuration:    DurationRange{Min: 120 * time.Millisecond, Max: 1150 * time.Millisecond},
			InterBurstPause:  DurationRange{Min: 2 * time.Millisecond, Max: 9 * time.Millisecond},
			InterRecordDelay: DurationRange{Min: 0, Max: 1 * time.Millisecond},
		},
		SessionProfile: SessionProfile{
			Duration:             DurationRange{Min: 240000 * time.Millisecond, Max: 2400000 * time.Millisecond},
			BurstsPerSession:     Range{Min: 120, Max: 900},
			TotalBytesPerSession: Range{Min: 180_000_000, Max: 1_000_000_000},
		},
		UploadDownloadRatio: 0.04,
		ConcurrentStreams:   Range{Min: 2, Max: 10},
	}
}

// DefaultWordPressProfile returns a built-in profile mimicking the
// **WordPress admin (`/wp-admin`) traffic pattern**: chunked HTML for the
// admin pages, periodic heartbeat polls (`admin-ajax.php?action=heartbeat`
// every 15-60s), occasional REST API calls. Pairs naturally with
// `chameleon_cookie=wordpress` and `chameleon_path=/wp-admin/admin-ajax.php`.
//
// Use this preset when the cover site is configured to look like a
// self-hosted WordPress install. Distinct from "saas-dashboard-default"
// because heartbeat traffic shape is unique enough that DPI heuristics
// trained on SaaS dashboards may flag it (and vice versa).
// v2: WordPress InterBurstPause trimmed to 80–250ms. The original 5–60s
// was the real shape of wp-admin heartbeat polling intervals but clamps
// to 250ms under the shaper cap anyway — using the post-cap range here
// keeps the sampling distribution honest.
func DefaultWordPressProfile() *SiteProfile {
	return &SiteProfile{
		Name:    "wordpress-admin-panel",
		Version: 1,
		RecordSizeDistribution: []SizeBucket{
			{MinSize: 64, MaxSize: 200, Weight: 0.25},      // heartbeat ping responses
			{MinSize: 200, MaxSize: 800, Weight: 0.20},     // small REST replies
			{MinSize: 800, MaxSize: 2000, Weight: 0.20},    // typical admin page chunks
			{MinSize: 2000, MaxSize: 5000, Weight: 0.20},   // edit-screen HTML
			{MinSize: 5000, MaxSize: 10000, Weight: 0.10},  // CSS/JS bundles
			{MinSize: 10000, MaxSize: 16384, Weight: 0.05}, // image uploads / preview
		},
		BurstPattern: BurstPattern{
			RecordsPerBurst:  Range{Min: 3, Max: 12},
			BurstDuration:    DurationRange{Min: 300 * time.Millisecond, Max: 1500 * time.Millisecond},
			InterBurstPause:  DurationRange{Min: 80 * time.Millisecond, Max: 250 * time.Millisecond},
			InterRecordDelay: DurationRange{Min: 0, Max: 80 * time.Millisecond},
		},
		SessionProfile: SessionProfile{
			Duration:             DurationRange{Min: 5 * time.Minute, Max: 30 * time.Minute},
			BurstsPerSession:     Range{Min: 10, Max: 60},
			TotalBytesPerSession: Range{Min: 200_000, Max: 5_000_000},
		},
		UploadDownloadRatio: 0.15, // form-heavy admin pattern
		ConcurrentStreams:   Range{Min: 1, Max: 4},
	}
}

// DefaultServerDownstreamProfile returns a built-in profile tuned for the
// **server→client half** of a persistent Chamele0nX H2 tunnel. Real SaaS
// dashboards are asymmetric: the client pokes the backend with small
// `events`/`poll` POSTs, the backend replies with large batched JSON
// bundles, HTML chunks, and asset streams. A symmetric "balanced"
// profile on both sides mis-models this — the server-side shape should
// bias toward larger records, bigger bursts, and shorter inter-burst
// pauses because a real server dispatches its response in one rush,
// not by "reading" between chunks.
//
// This profile is the downstream companion to [DefaultBalancedProfile]
// (upstream client). Together they reproduce the natural SaaS shape:
// small upstream bursts ↔ bulky downstream batches, both sides still
// record-split + burst-paused (symmetric defense against passive DPI).
//
// Parameters:
//   - RecordsPerBurst 15–30: larger than SaaS (5–15) but shy of
//     Aggressive (15–40). Matches how server frameworks flush a single
//     response in one batch of many TLS records.
//   - InterBurstPause 20–80ms: well under the 250ms inline cap, so
//     BypassPauseCap is not required. Still injects enough timing
//     entropy to defeat the v1 "continuous stream" ML-DPI signal.
//   - Record size distribution biased toward 5–16KB (half the weight),
//     mirroring JS/CSS bundles, chunked HTML, and image deliveries.
//   - BurstDuration 100–600ms and InterRecordDelay 0–5ms: fast fire,
//     consistent with a server pushing a batched response.
//
// Rationale for shipping this as a distinct profile (not retuning
// DefaultSaaSProfile): the SaaS profile is correct for the **client
// side** where small API POSTs dominate, and retuning it would make
// client-side upstream bulkier than real dashboards send. Keeping them
// split preserves asymmetric realism.
//
// Throughput target: ≥7 Mbps sustained on downstream path with v2
// symmetric shaping active on both sides. Validated by
// TestDefaultServerDownstreamThroughput in shaped_conn_test.go.
func DefaultServerDownstreamProfile() *SiteProfile {
	return &SiteProfile{
		Name:    "saas-server-downstream",
		Version: 1,
		RecordSizeDistribution: []SizeBucket{
			{MinSize: 64, MaxSize: 200, Weight: 0.05},      // response headers
			{MinSize: 200, MaxSize: 800, Weight: 0.10},     // small status replies
			{MinSize: 800, MaxSize: 2000, Weight: 0.15},    // small JSON responses
			{MinSize: 2000, MaxSize: 5000, Weight: 0.20},   // typical API payloads
			{MinSize: 5000, MaxSize: 10000, Weight: 0.25},  // medium bundles
			{MinSize: 10000, MaxSize: 16384, Weight: 0.25}, // large assets, JS chunks
		},
		BurstPattern: BurstPattern{
			RecordsPerBurst:  Range{Min: 15, Max: 30},
			BurstDuration:    DurationRange{Min: 100 * time.Millisecond, Max: 600 * time.Millisecond},
			InterBurstPause:  DurationRange{Min: 20 * time.Millisecond, Max: 80 * time.Millisecond},
			InterRecordDelay: DurationRange{Min: 0, Max: 5 * time.Millisecond},
		},
		SessionProfile: SessionProfile{
			Duration:             DurationRange{Min: 3 * time.Minute, Max: 20 * time.Minute},
			BurstsPerSession:     Range{Min: 30, Max: 150},
			TotalBytesPerSession: Range{Min: 1_000_000, Max: 30_000_000},
		},
		UploadDownloadRatio: 0.05, // server = download-heavy
		ConcurrentStreams:   Range{Min: 1, Max: 8},
	}
}

// DefaultClientUpstreamProfile returns a built-in profile tuned for the
// **client→server half** of a persistent Chamele0nX H2 tunnel, and is the
// profile a connection falls back to when no `chameleon_profile` is named.
//
// Why this exists: [DefaultServerDownstreamProfile] was added after field
// testing showed [DefaultSaaSProfile] crippled the server's downstream
// path (see TestShapedConnProfileThroughput). The client's upstream half
// kept falling back to DefaultSaaSProfile, and it has the same defect for
// the same reason — a burst of 5–15 records averaging ~2.6KB is ~26KB of
// payload, and after every one of them the shaper sleeps a 50–250ms
// inter-burst pause. That is a hard ceiling around 0.2 MB/s no matter how
// fast the link is. Measured against the production server on 2026-09-09:
// 0.12 MB/s upstream on DefaultSaaSProfile against 2.5 MB/s unshaped on
// the same box, while downstream (shaped by the server's own profile) ran
// at line rate. Anything that uploads — a photo, a call, a form post —
// crawls, and the tunnel reads as "the internet barely works".
//
// The shape here keeps the disguise rather than dropping it:
//
//   - Records are still split and jittered on every write, which is the
//     primary defence (see the package doc). Only the pause budget moves.
//   - The size distribution starts at 512 bytes because that is where
//     shaping starts at all: writes below minShapingThreshold pass
//     through untouched, so the shaped path only ever carries bulk. A
//     distribution weighted for small API chatter mis-models it — the
//     small records the profile spends its budget on are the ones the
//     shaper never emits.
//   - InterBurstPause 20–90ms keeps genuine timing entropy between
//     bursts, in the same band as the downstream companion, so
//     back-to-back-record detection still has nothing to lock onto.
//
// The honest trade: bursts are longer than a real dashboard's upstream,
// so a classifier looking at upstream burst *volume* sees a browser
// uploading a file rather than one idling on a page. That is a shape real
// clients produce; a 0.2 MB/s ceiling is not something users tolerate.
// Operators who want the old behaviour keep it by naming "balanced".
//
// Pairs with [DefaultServerDownstreamProfile] on the server side.
func DefaultClientUpstreamProfile() *SiteProfile {
	return &SiteProfile{
		Name:    "saas-client-upstream",
		Version: 1,
		RecordSizeDistribution: []SizeBucket{
			{MinSize: 512, MaxSize: 1500, Weight: 0.10},   // request bodies
			{MinSize: 1500, MaxSize: 4000, Weight: 0.20},  // form posts, small blobs
			{MinSize: 4000, MaxSize: 9000, Weight: 0.30},  // upload chunks
			{MinSize: 9000, MaxSize: 16384, Weight: 0.40}, // bulk upload
		},
		BurstPattern: BurstPattern{
			RecordsPerBurst:  Range{Min: 18, Max: 44},
			BurstDuration:    DurationRange{Min: 120 * time.Millisecond, Max: 700 * time.Millisecond},
			InterBurstPause:  DurationRange{Min: 20 * time.Millisecond, Max: 90 * time.Millisecond},
			InterRecordDelay: DurationRange{Min: 0, Max: 4 * time.Millisecond},
		},
		SessionProfile: SessionProfile{
			Duration:             DurationRange{Min: 3 * time.Minute, Max: 20 * time.Minute},
			BurstsPerSession:     Range{Min: 20, Max: 140},
			TotalBytesPerSession: Range{Min: 500_000, Max: 20_000_000},
		},
		UploadDownloadRatio: 0.3, // this half IS the upload half
		ConcurrentStreams:   Range{Min: 1, Max: 8},
	}
}

// DefaultLowPowerProfile returns a built-in profile tuned for
// **mobile/embedded constraints**: small bursts, long pauses, low CPU
// pressure on the shaper. Less aggressive than Stealth on the timing
// dimensions but still distinctly non-bulk. Use on weaker hardware
// (older Android, IoT, battery-constrained devices) where the per-record
// CPU cost of fine-grained shaping is itself a concern.
// v2: LowPower InterBurstPause trimmed to 100–250ms. The 5–60s original
// range reflected low-activity idle patterns but is effectively clamped
// under the shaper cap. Short pauses also reduce wall-clock time spent
// holding writeMu on battery-constrained devices where every sleep is a
// missed opportunity to batch work.
func DefaultLowPowerProfile() *SiteProfile {
	return &SiteProfile{
		Name:    "lowpower-mobile-friendly",
		Version: 1,
		RecordSizeDistribution: []SizeBucket{
			{MinSize: 64, MaxSize: 500, Weight: 0.30},
			{MinSize: 500, MaxSize: 2000, Weight: 0.40},
			{MinSize: 2000, MaxSize: 5000, Weight: 0.20},
			{MinSize: 5000, MaxSize: 10000, Weight: 0.10},
		},
		BurstPattern: BurstPattern{
			RecordsPerBurst:  Range{Min: 2, Max: 6},
			BurstDuration:    DurationRange{Min: 500 * time.Millisecond, Max: 3 * time.Second},
			InterBurstPause:  DurationRange{Min: 100 * time.Millisecond, Max: 250 * time.Millisecond},
			InterRecordDelay: DurationRange{Min: 1 * time.Millisecond, Max: 50 * time.Millisecond},
		},
		SessionProfile: SessionProfile{
			Duration:             DurationRange{Min: 5 * time.Minute, Max: 20 * time.Minute},
			BurstsPerSession:     Range{Min: 5, Max: 25},
			TotalBytesPerSession: Range{Min: 100_000, Max: 3_000_000},
		},
		UploadDownloadRatio: 0.12,
		ConcurrentStreams:   Range{Min: 1, Max: 3},
	}
}

// PersonalizeFor returns a deep copy of the profile with per-client jitter
// applied to the size-bucket weights, RecordsPerBurst range, and
// InterBurstPause range. Jitter is fully deterministic from seed — same
// seed always produces the same personalized profile, so shaping is
// stable within one connection while diverging between users.
//
// This closes a cross-client correlation weakness: without
// personalization, every Chamele0nX user shares identical bucket envelopes
// and burst patterns, making them mutually correlatable on the wire even
// though per-record sizes are jittered. PersonalizeFor diverges the
// envelopes themselves, so two clients on the same nominal preset look
// like two users on slightly different real sites instead of two
// instances of the same VPN.
//
// Jitter ranges:
//   - SizeBucket.Weight: ±20%, then re-normalized so weights sum to 1.0
//   - RecordsPerBurst.Min/Max: ±30% (independent jitter on each end)
//   - InterBurstPause.Min/Max: ±50% (independent jitter on each end)
//
// Other fields (record-size min/max bounds, BurstDuration, InterRecord-
// Delay, SessionProfile, UploadDownloadRatio, ConcurrentStreams,
// BypassPauseCap, Name, Version) are copied unchanged — they describe
// the profile *type*, not its per-client expression.
//
// seed=0 is treated as "no personalization" — returns the profile
// unchanged. This lets test code use NewShapedConn(seed=0) without
// having values shifted out from under their expectations.
//
// Returns nil if p is nil.
func (p *SiteProfile) PersonalizeFor(seed uint64) *SiteProfile {
	if p == nil {
		return nil
	}
	if seed == 0 {
		return p
	}

	cp := *p // shallow copy of value-type fields

	// Deep-copy the size distribution and jitter weights ±20%.
	cp.RecordSizeDistribution = make([]SizeBucket, len(p.RecordSizeDistribution))
	var totalWeight float64
	for i, b := range p.RecordSizeDistribution {
		s := mixSeed(seed, uint64(i+1))
		j := personalizedFloat(s, -0.20, 0.20)
		w := b.Weight * (1.0 + j)
		if w < 0.001 {
			w = 0.001 // floor to keep the bucket reachable
		}
		cp.RecordSizeDistribution[i] = SizeBucket{
			MinSize: b.MinSize,
			MaxSize: b.MaxSize,
			Weight:  w,
		}
		totalWeight += w
	}
	// Re-normalize so weights sum to 1.0 (Validate requires this).
	if totalWeight > 0 {
		for i := range cp.RecordSizeDistribution {
			cp.RecordSizeDistribution[i].Weight /= totalWeight
		}
	}

	// Burst pattern jitter — copy the struct, then jitter the two ranges
	// that the shaper actually samples from. BurstDuration and
	// InterRecordDelay are too narrow to give DPI a useful signal, leave
	// them alone to keep the personalization predictable.
	cp.BurstPattern = p.BurstPattern
	cp.BurstPattern.RecordsPerBurst = jitterIntRange(
		p.BurstPattern.RecordsPerBurst,
		mixSeed(seed, 100),
		0.30,
		1, // floor: at least 1 record per burst
	)
	cp.BurstPattern.InterBurstPause = jitterDurationRange(
		p.BurstPattern.InterBurstPause,
		mixSeed(seed, 101),
		0.50,
		0, // floor: 0 (some profiles legitimately want zero-min)
	)

	cp.Name = p.Name + "-personal"
	return &cp
}

// mixSeed deterministically combines a base seed with a slot index.
// splitmix64 step (Sebastiano Vigna). Used to derive sub-seeds for
// independent jitter axes from one master seed.
func mixSeed(seed, slot uint64) uint64 {
	z := seed + slot*0x9E3779B97F4A7C15
	z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9
	z = (z ^ (z >> 27)) * 0x94D049BB133111EB
	return z ^ (z >> 31)
}

// personalizedFloat maps a 64-bit seed into a float in [lo, hi].
// Uniform-ish; quality is fine for jitter purposes (we don't need
// statistical uniformity — just per-seed determinism).
func personalizedFloat(seed uint64, lo, hi float64) float64 {
	f := float64(seed&0xFFFFFFFF) / float64(uint32(0xFFFFFFFF))
	return lo + (hi-lo)*f
}

// jitterIntRange shifts both ends of a Range by ±pct (deterministic
// from seed). Each end uses an independent sub-seed so they don't
// collapse together.
func jitterIntRange(r Range, seed uint64, pct float64, floor int) Range {
	minJitter := personalizedFloat(mixSeed(seed, 1), -pct, pct)
	maxJitter := personalizedFloat(mixSeed(seed, 2), -pct, pct)
	minVal := int(float64(r.Min) * (1.0 + minJitter))
	maxVal := int(float64(r.Max) * (1.0 + maxJitter))
	if minVal < floor {
		minVal = floor
	}
	if maxVal < minVal {
		maxVal = minVal
	}
	return Range{Min: minVal, Max: maxVal}
}

// jitterDurationRange is the time.Duration analogue of jitterIntRange.
func jitterDurationRange(r DurationRange, seed uint64, pct float64, floor time.Duration) DurationRange {
	minJitter := personalizedFloat(mixSeed(seed, 1), -pct, pct)
	maxJitter := personalizedFloat(mixSeed(seed, 2), -pct, pct)
	minVal := time.Duration(float64(r.Min) * (1.0 + minJitter))
	maxVal := time.Duration(float64(r.Max) * (1.0 + maxJitter))
	if minVal < floor {
		minVal = floor
	}
	if maxVal < minVal {
		maxVal = minVal
	}
	return DurationRange{Min: minVal, Max: maxVal}
}

// BuiltInProfileByName looks up a built-in [SiteProfile] by short name.
// Recognized names: "balanced" (alias "saas"), "stealth", "aggressive",
// "wordpress" (alias "wp"), "lowpower" (alias "low-power", "mobile"),
// "server-downstream" (alias "server", "downstream", "fast-server"),
// "saas-stealth" (alias "saas_stealth"), "saas-fast" (alias "saas_fast")
// and "saas-max" (alias "saas_max"). The last three mirror the profiles
// shipped under deploy/profiles/ so a share link minted from a server
// configured with one of them resolves to a struct on the client instead
// of being mistaken for a filesystem path.
// Returns nil if the name is unknown — caller should fall back to a
// file-based [LoadProfile] or [DefaultSaaSProfile].
//
// Names are matched case-insensitively after trimming. This is the
// public API used by the gomobile facade and the chamele0nx transport's
// connect() path to wire `endpoint.Params["chameleon_profile"]` to a
// concrete profile struct without touching the filesystem.
func BuiltInProfileByName(name string) *SiteProfile {
	switch strings.ToLower(strings.TrimSpace(name)) {
	case "balanced", "saas", "saas-dashboard", "default":
		return DefaultBalancedProfile()
	case "stealth", "stealth-admin", "admin-console":
		return DefaultStealthProfile()
	case "aggressive", "bulk", "performance":
		return DefaultAggressiveProfile()
	case "wordpress", "wp", "wp-admin":
		return DefaultWordPressProfile()
	case "lowpower", "low-power", "mobile", "embedded":
		return DefaultLowPowerProfile()
	case "server-downstream", "server", "downstream", "fast-server":
		return DefaultServerDownstreamProfile()
	case "client-upstream", "client", "upstream":
		return DefaultClientUpstreamProfile()
	case "saas-stealth", "saas_stealth":
		return DefaultSaaSStealthProfile()
	case "saas-fast", "saas_fast":
		return DefaultSaaSFastProfile()
	case "saas-max", "saas_max":
		return DefaultSaaSMaxProfile()
	default:
		return nil
	}
}

// Burst is one burst of records sampled from a profile: the sizes to
// emit, the delay to leave between them, and the pause to take once the
// burst is finished. GenerateBurst produces it and chamele0nx-validator
// consumes it to generate synthetic traffic for its statistical tests.
type Burst struct {
	// RecordSizes are the target payload sizes, one per TLS record.
	RecordSizes []int
	// InterRecordDelay is the gap between records inside the burst.
	InterRecordDelay time.Duration
	// PostBurstPause is the gap after the burst, standing in for the
	// time a reader spends on a page before asking for the next one.
	PostBurstPause time.Duration
}

// GenerateBurst creates a burst of record sizes from the profile,
// randomized with the per-client seed (±pct jitter per FOCI 2024).
func (p *SiteProfile) GenerateBurst(clientSeed uint64) (Burst, error) {
	bp := p.BurstPattern

	numRecords, err := cryptoRandRange(bp.RecordsPerBurst.Min, bp.RecordsPerBurst.Max)
	if err != nil {
		return Burst{}, err
	}

	sizes := make([]int, numRecords)
	for i := range sizes {
		size, err := p.sampleRecordSize()
		if err != nil {
			return Burst{}, err
		}
		// Per-client jitter using the seed, one derived seed per record.
		// The width is the shared RecordJitterPercent rather than a literal:
		// the validator's reference distribution is built from that same
		// constant, and a burst generated with a different width would be
		// measured against a model of traffic nobody emits.
		derivedSeed := clientSeed ^ uint64(i)*0x9E3779B97F4A7C15
		sizes[i] = RandomizeSize(size, derivedSeed, RecordJitterPercent)
	}

	interDelay, err := cryptoRandDuration(bp.InterRecordDelay.Min, bp.InterRecordDelay.Max)
	if err != nil {
		return Burst{}, err
	}

	postPause, err := cryptoRandDuration(bp.InterBurstPause.Min, bp.InterBurstPause.Max)
	if err != nil {
		return Burst{}, err
	}

	return Burst{
		RecordSizes:      sizes,
		InterRecordDelay: interDelay,
		PostBurstPause:   postPause,
	}, nil
}

// sampleRecordSize picks a random record size from the distribution.
func (p *SiteProfile) sampleRecordSize() (int, error) {
	// Weighted random selection.
	var r [8]byte
	if _, err := rand.Read(r[:]); err != nil {
		return 0, err
	}
	val := float64(binary.LittleEndian.Uint64(r[:])) / float64(math.MaxUint64)

	cumulative := 0.0
	for _, b := range p.RecordSizeDistribution {
		cumulative += b.Weight
		if val <= cumulative {
			// Pick random size within bucket.
			size, err := cryptoRandRange(b.MinSize, b.MaxSize)
			if err != nil {
				return 0, err
			}
			return size, nil
		}
	}

	// Fallback to last bucket.
	last := p.RecordSizeDistribution[len(p.RecordSizeDistribution)-1]
	return cryptoRandRange(last.MinSize, last.MaxSize)
}

// cryptoRandRange returns a cryptographically random int in [min, max].
func cryptoRandRange(min, max int) (int, error) {
	if min >= max {
		return min, nil
	}
	n, err := cryptoRandIntn(max - min + 1)
	if err != nil {
		return 0, err
	}
	return min + n, nil
}

// cryptoRandDuration returns a random duration in [min, max].
func cryptoRandDuration(min, max time.Duration) (time.Duration, error) {
	if min >= max {
		return min, nil
	}
	n, err := cryptoRandInt64n(int64(max-min) + 1)
	if err != nil {
		return 0, err
	}
	return min + time.Duration(n), nil
}

// cryptoRandLogUniform returns a duration drawn log-uniformly from
// [min, max]. Its density is proportional to 1/t, so short pauses are
// weighted more heavily and long ones taper off — the heavy-tailed shape
// real inter-request timing has, rather than the flat spread of a uniform
// draw. The result never leaves [min, max], so a caller can treat max as
// a hard upper bound without clamping after the fact (clamping would pile
// every over-bound draw onto one value and create a point mass there).
func cryptoRandLogUniform(min, max time.Duration) (time.Duration, error) {
	if min >= max {
		return min, nil
	}
	if min <= 0 {
		// The 1/t density is undefined at zero. A uniform draw over the
		// same range is the sensible fallback and has no point mass.
		return cryptoRandDuration(min, max)
	}

	// u is a fixed-point uniform in [0, 1). denom fits in a 32-bit int so
	// this stays correct on every target architecture.
	const denom = 1 << 30
	ri, err := cryptoRandIntn(denom)
	if err != nil {
		return 0, err
	}
	u := float64(ri) / float64(denom)

	ratio := float64(max) / float64(min)
	out := time.Duration(float64(min) * math.Pow(ratio, u))
	// Guard the float round-trip against landing a nanosecond outside
	// the range.
	if out < min {
		out = min
	}
	if out > max {
		out = max
	}
	return out, nil
}
